<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Portfolio Contact Section</title>
    <style>
        :root {
            --bg-body: #050507;
            --bg-card: #0f1115;
            --bg-card-hover: #161921;
            --text-primary: #ffffff;
            --text-secondary: #94a3b8;
            --text-muted: #64748b;
            --accent-blue: #38bdf8;
            --accent-purple: #c084fc;
            --accent-pink: #f472b6;
            --border-color: rgba(255, 255, 255, 0.08);
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-body);
            color: var(--text-primary);
            font-family: var(--font-sans);
            line-height: 1.5;
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            overflow-x: hidden;
        }

        /* --- Header / Navbar --- */
        header {
            position: fixed;
            top: 0;
            width: 100%;
            height: 70px;
            background: rgba(5, 5, 7, 0.85);
            backdrop-filter: blur(12px);
            border-bottom: 1px solid var(--border-color);
            z-index: 100;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 40px;
        }

        .brand {
            display: flex;
            align-items: center;
            gap: 12px;
            font-weight: 600;
            font-size: 1.1rem;
        }

        .avatar {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-weight: bold;
            font-size: 14px;
        }

        nav {
            display: flex;
            gap: 32px;
        }

        nav a {
            text-decoration: none;
            color: var(--text-secondary);
            font-size: 0.95rem;
            transition: color 0.2s;
        }

        nav a:hover {
            color: white;
        }

        .header-icons {
            display: flex;
            gap: 20px;
            color: var(--text-secondary);
        }

        .header-icon {
            cursor: pointer;
            transition: color 0.2s;
        }
        .header-icon:hover { color: white; }

        /* --- Main Layout (Simulating the screenshot context) --- */
        main {
            flex: 1;
            padding-top: 90px; /* Space for fixed header */
            max-width: 1400px;
            margin: 0 auto;
            width: 100%;
            padding-left: 40px;
            padding-right: 40px;
            display: grid;
            grid-template-columns: repeat(3, 1fr); /* Top row of cards */
            gap: 24px;
            margin-bottom: 60px;
        }

        /* Placeholder cards for the "Projects" row visible in screenshot */
        .placeholder-card {
            background-color: var(--bg-card);
            border-radius: 16px;
            border: 1px solid var(--border-color);
            height: 180px;
            padding: 20px;
            opacity: 0.4; /* Dimmed to focus on contact section */
            pointer-events: none;
        }

        .tag-row {
            display: flex;
            gap: 10px;
            margin-top: auto;
        }

        .tag {
            font-size: 12px;
            padding: 4px 10px;
            border-radius: 20px;
            background: rgba(255,255,255,0.05);
            color: var(--text-muted);
        }

        /* --- Contact Section (The Target) --- */
        .contact-section {
            grid-column: 1 / -1; /* Span full width */
            background-color: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 24px;
            padding: 48px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            position: relative;
            box-shadow: 0 20px 40px rgba(0,0,0,0.2);
        }

        .contact-content {
            max-width: 600px;
        }

        .label {
            font-size: 0.85rem;
            letter-spacing: 0.15em;
            text-transform: uppercase;
            color: var(--accent-purple); /* Using purple/blue mix */
            margin-bottom: 16px;
            font-weight: 700;
        }

        h2 {
            font-size: 3.2rem;
            line-height: 1.1;
            margin-bottom: 20px;
            font-weight: 800;
            letter-spacing: -0.02em;
        }

        .highlight-text {
            background: linear-gradient(90deg, var(--accent-blue), var(--accent-purple));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        p.description {
            color: var(--text-secondary);
            font-size: 1.05rem;
            margin-bottom: 32px;
            max-width: 500px;
            line-height: 1.6;
        }

        .cta-btn {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            background-color: white;
            color: black;
            padding: 14px 28px;
            border-radius: 99px;
            text-decoration: none;
            font-weight: 600;
            font-size: 0.95rem;
            transition: transform 0.2s ease, box-shadow 0.2s ease;
            box-shadow: 0 4px 12px rgba(255,255,255,0.1);
        }

        .cta-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 20px rgba(255,255,255,0.15);
        }

        /* --- Contact Cards List --- */
        .contact-cards-container {
            display: flex;
            flex-direction: column;
            gap: 16px;
            min-width: 320px;
        }

        .contact-card {
            display: flex;
            align-items: center;
            background: rgba(255, 255, 255, 0.03);
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: 16px 20px;
            text-decoration: none;
            color: inherit;
            transition: all 0.3s ease;
            position: relative;
            overflow: hidden;
        }

        .contact-card:hover {
            background: var(--bg-card-hover);
            border-color: rgba(255,255,255,0.15);
            transform: translateX(4px);
        }

        .card-icon-wrapper {
            width: 44px;
            height: 44px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-right: 16px;
            flex-shrink: 0;
        }

        /* Specific Icon Colors */
        .icon-email { background: rgba(56, 189, 248, 0.1); color: var(--accent-blue); }
        .icon-github { background: rgba(192, 132, 252, 0.1); color: var(--accent-purple); }
        .icon-linkedin { background: rgba(244, 114, 182, 0.1); color: var(--accent-pink); }

        .card-info {
            flex: 1;
        }

        .card-label {
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--text-muted);
            margin-bottom: 2px;
        }

        .card-value {
            font-size: 0.95rem;
            font-weight: 500;
            color: var(--text-primary);
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .arrow-icon {
            opacity: 0;
            transform: translateX(-5px);
            transition: all 0.2s ease;
            font-size: 1.2rem;
        }

        .contact-card:hover .arrow-icon {
            opacity: 1;
            transform: translateX(0);
        }

        /* Footer/Bottom */
        .bottom-nav {
            position: fixed;
            bottom: 30px;
            left: 40px;
            width: 40px;
            height: 40px;
            border-radius: 50%;
            border: 1px solid var(--border-color);
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            color: white;
            background: rgba(0,0,0,0.5);
            backdrop-filter: blur(4px);
            z-index: 200;
        }

        /* Responsive */
        @media (max-width: 1024px) {
            main { grid-template-columns: 1fr; }
            .placeholder-card { display: none; } /* Hide placeholders on small screens */

            .contact-section {
                flex-direction: column;
                align-items: flex-start;
                gap: 40px;
            }

            .contact-cards-container {
                width: 100%;
            }
        }
    </style>
</head>
